        self._buffer.clear()


def create_writer(format: str, output_path: str, **kwargs: Any) -> BaseWriter:
    """Factory function to create the appropriate writer."""
    writers = {
        "json": JsonWriter,
        "csv": CsvWriter,
        "null": NullWriter,
    }
    cls = writers.get(format)
    if cls is None:
        raise ValueError(f"Unknown writer format: {format}. Available: {list(writers.keys())}")
    return cast(cls, cls(output_path, **kwargs))


def write_records(
    records: list[Record], output_path: str, format: str = "json", **kwargs: Any
) -> BatchResult:
    """Convenience function to write a list of records to a file."""
    result = BatchResult()
    start = time.time()
    try:
        writer = create_writer(format, output_path, **kwargs)
        for record in records:
            writer.write_record(record)
        writer.close()
        result.success = len(records)
    except Exception as e:
        result.failed += 1
        result.errors.append(str(e))
    finally:
        result.duration_ms = (time.time() - start) * 1000
    return result
